// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/healthz", wrapper.Healthz)
	router.GET(options.BaseURL+"/v1/gpus", wrapper.ListGpus)
	router.GET(options.BaseURL+"/v1/gpus/:gpuRef", wrapper.GetGpu)
	router.POST(options.BaseURL+"/v1/gpus/:gpuRef/partition", wrapper.ChangePartition)
	router.GET(options.BaseURL+"/v1/containers", wrapper.ListContainers)
	router.POST(options.BaseURL+"/v1/containers", wrapper.CreateContainer)
	router.DELETE(options.BaseURL+"/v1/containers/:namespace/:name", wrapper.DeleteContainer)
	router.GET(options.BaseURL+"/v1/containers/:namespace/:name", wrapper.GetContainer)
	router.POST(options.BaseURL+"/v1/containers/:namespace/:name/start", wrapper.StartContainer)
	router.GET(options.BaseURL+"/v1/vms", wrapper.ListVms)
	router.POST(options.BaseURL+"/v1/vms", wrapper.CreateVm)
	router.DELETE(options.BaseURL+"/v1/vms/:namespace/:name", wrapper.DeleteVm)
	router.GET(options.BaseURL+"/v1/vms/:namespace/:name", wrapper.GetVm)
	router.PATCH(options.BaseURL+"/v1/vms/:namespace/:name", wrapper.UpdateVm)
	router.POST(options.BaseURL+"/v1/vms/:namespace/:name/stop", wrapper.StopVm)
	router.POST(options.BaseURL+"/v1/vms/:namespace/:name/start", wrapper.StartVm)
	router.GET(options.BaseURL+"/v1/volumes", wrapper.ListVolumes)
	router.POST(options.BaseURL+"/v1/volumes", wrapper.CreateVolume)
	router.DELETE(options.BaseURL+"/v1/volumes/:namespace/:name", wrapper.DeleteVolume)
}

